use super::*;

/// 🪢️ Exact edge-set admission precedes one atomic authored edge write on the same original owner.
#[test]
fn original_mesh_tessellation_edge_emission_prices_exact_atomic_output(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use protocol::value::{retained_clone::{RetainedCloneGrant,RetainedCloneProgress},retirement::controlled::ControlledRetirement};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧫️fixtures/🧩️tessellation/🎟️owners.json")).unwrap();
    for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){
        let(mut job,source)=observe(||{let mut job=MeshTessellationJob::new(super::tessellation_metadata_tests::authored_source(&law));while !job.buffer_reservation_complete(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:job.next_buffer_capacity_byte_demand(0).unwrap(),maximum_release_bytes:0,maximum_depth:job.next_buffer_depth_demand().unwrap()};job.reserve_buffer_step(grant).unwrap();}while !job.metadata_capture_complete(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:job.next_metadata_depth_demand().unwrap()};job.capture_metadata_step(grant).unwrap();}while job.phase!=7{job.advance().unwrap();}job});
        let original=job.mesh.vertices.as_ptr();let out=job.output.as_ref().unwrap();let pointers=(out.edge_positions.as_ptr(),out.edge_uvs.as_ptr(),out.edge_ids.as_ptr(),out.edge_is_seam.as_ptr());let(mut born,mut freed,mut turns)=(source.0,source.1,0);
        loop{
            let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:law["edgeEmission"]["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:job.next_edge_capacity_byte_demand(0,45).unwrap(),maximum_release_bytes:job.next_edge_release_byte_demand(0).unwrap(),maximum_depth:job.next_edge_depth_demand(0).unwrap()};
            for denied in [RetainedCloneGrant {maximum_items:0,..grant},RetainedCloneGrant {maximum_capacity_bytes:grant.maximum_capacity_bytes.saturating_sub(1),..grant},RetainedCloneGrant {maximum_depth:grant.maximum_depth.saturating_sub(1),..grant}]{if denied==grant{continue;}let(step,heap)=observe(||job.emit_edge_step(0,denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(job.edge_receipt.0,RetainedCloneProgress::default());assert_eq!(heap,(0,0));let out=job.output.as_ref().unwrap();assert!(out.edge_positions.is_empty()&&out.edge_uvs.is_empty()&&out.edge_ids.is_empty()&&out.edge_is_seam.is_empty());assert_eq!((out.edge_positions.as_ptr(),out.edge_uvs.as_ptr(),out.edge_ids.as_ptr(),out.edge_is_seam.as_ptr()),pointers);assert_eq!(job.mesh.vertices.as_ptr(),original);}
            if job.next_edge_copy_byte_demand(0).unwrap()!=0{for copy in[0,1,3,44]{let(step,heap)=observe(||job.emit_edge_step(0,RetainedCloneGrant {maximum_copy_bytes:copy,..grant}).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert!(job.output.as_ref().unwrap().edge_positions.is_empty());}}
            let(step,heap)=observe(||job.emit_edge_step(0,grant).unwrap());let receipt=step.progress();assert_eq!(receipt,job.edge_receipt.0);assert!(receipt.fits(grant));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100);if matches!(step,protocol::value::retained_clone::RetainedCloneStep::Complete(_)){assert_eq!(receipt.copied_bytes,law["edgeEmission"]["copyBytes"].as_u64().unwrap()as usize);break;}
        }
        let out=job.output.as_ref().unwrap();assert_eq!(out.edge_positions,serde_json::from_value::<Vec<f32>>(law["edgeEmission"]["positions"].clone()).unwrap());assert_eq!(out.edge_uvs,serde_json::from_value::<Vec<f32>>(law["edgeEmission"]["uvs"].clone()).unwrap());assert_eq!(out.edge_ids,[law["edgeEmission"]["edgeId"].as_u64().unwrap()as u32]);assert_eq!(out.edge_is_seam,[law["edgeEmission"]["isSeam"].as_u64().unwrap()as u8]);assert_eq!((out.edge_positions.as_ptr(),out.edge_uvs.as_ptr(),out.edge_ids.as_ptr(),out.edge_is_seam.as_ptr()),pointers);assert_eq!(job.mesh.vertices.as_ptr(),original);
        let(mut owner,handoff)=observe(||ControlledRetirement::new(job).unwrap_or_else(|_|panic!("original edge closure unsupported")));assert_eq!(handoff,(0,0));while !owner.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(close_copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe(||owner.step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);}
        assert_eq!(born,freed);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Mesh atomic edge copied=45 underAtomic1and3Refused=true sameSource=true sameBacking=true physical={freed} closeCopy={close_copy} terminalDrop=0");
    }
}
